def move_num(s):
    letters, numbers = [], []

    current_number = []
    for char in s:
        if char.isdigit():
            current_number.append(char)
        else:
            if current_number:
                numbers.append(''.join(current_number))
                current_number = []
            letters.append(char)

    # Append any remaining number at the end of the string
    if current_number:
        numbers.append(''.join(current_number))

    return ''.join(letters) + ''.join(numbers)

# Example usage and test
assert move_num('I1love143you55three3000thousand') == 'Iloveyouthreethousand1143553000'
```

