def tuple_to_dict(input_tuple):
    """
    Convert a given tuple into a dictionary where adjacent elements form key-value pairs.

    Args:
    input_tuple (tuple): The input tuple containing elements.

    Returns:
    dict: A dictionary with adjacent elements as key-value pairs.
    """
    # Use dictionary comprehension with step of 2
    return {input_tuple[i]: input_tuple[i+1] for i in range(0, len(input_tuple) - 1, 2)}

# Example usage and testing
assert tuple_to_dict((1, 5, 7, 10, 13, 5)) == {1: 5, 7: 10, 13: 5}
assert tuple_to_dict((4, 9, 11, 2)) == {4: 9, 11: 2}
assert tuple_to_dict(()) == {}
assert tuple_to_dict((1,)) == {}
```

